import{c as e,Q as t,j as s,m as o}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第四章：首次对话","description":"学会和 Claude Code 对话，并掌握头三个必会的按键与命令","frontmatter":{"title":"第四章：首次对话","description":"学会和 Claude Code 对话，并掌握头三个必会的按键与命令","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/quickstart"},"headers":[],"relativePath":"guide/1-getting-started/4-first-conversation.md","filePath":"guide/1-getting-started/4-first-conversation.md"}'),i={name:"guide/1-getting-started/4-first-conversation.md"};function d(c,a,l,n,p,r){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="第四章-首次对话" tabindex="-1">第四章：首次对话 <a class="header-anchor" href="#第四章-首次对话" aria-label="Permalink to &quot;第四章：首次对话&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能开一个会话、问出好问题，并知道 <code>Shift+Tab</code>、<code>/init</code>、<code>/context</code> 这三个最常用的入口。</p></div><h2 id="启动对话" tabindex="-1">启动对话 <a class="header-anchor" href="#启动对话" aria-label="Permalink to &quot;启动对话&quot;">​</a></h2><p>在项目文件夹里打开终端，然后：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 你的项目文件夹</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">为什么要 cd 到项目里</p><p>Claude Code 的工作范围就是<strong>你启动它的那个文件夹</strong>。在 <code>~</code> 目录下启动，它看不到你的项目。养成&quot;先 cd 再 claude&quot;的习惯。</p></div><h3 id="你好" tabindex="-1">你好！ <a class="header-anchor" href="#你好" aria-label="Permalink to &quot;你好！&quot;">​</a></h3><p>直接用中文问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，Claude！</span></span></code></pre></div><p>它就会用中文回复你。</p><h2 id="三个要立刻记住的操作" tabindex="-1">三个要立刻记住的操作 <a class="header-anchor" href="#三个要立刻记住的操作" aria-label="Permalink to &quot;三个要立刻记住的操作&quot;">​</a></h2><p>新手期只需要这三个，其他都可以以后再说。</p><h3 id="_1-shift-tab-——-切换它问不问你就动手" tabindex="-1">1. <code>Shift + Tab</code> —— 切换它问不问你就动手 <a class="header-anchor" href="#_1-shift-tab-——-切换它问不问你就动手" aria-label="Permalink to &quot;1. `Shift + Tab` —— 切换它问不问你就动手&quot;">​</a></h3><p>按一下 <code>Shift + Tab</code>，输入框下方会显示当前权限模式。默认是<strong>自动模式</strong>：读文件、跑测试这类安全操作它直接做，删文件、push 到远端这类危险操作会拦下来问你。</p><p>不确定它在干什么的时候，切到&quot;每次都要问&quot;的模式，看完几轮再切回来。详见第十七章。</p><h3 id="_2-init-——-让它先认识你的项目" tabindex="-1">2. <code>/init</code> —— 让它先认识你的项目 <a class="header-anchor" href="#_2-init-——-让它先认识你的项目" aria-label="Permalink to &quot;2. `/init` —— 让它先认识你的项目&quot;">​</a></h3><p>第一次在某个项目里用它，先运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/init</span></span></code></pre></div><p>它会读一遍你的项目，生成一个 <code>CLAUDE.md</code>，把技术栈、常用命令、目录约定记下来。<strong>以后每次开会话它都会自动读这个文件</strong>，省掉反复解释。这是投入产出比最高的一步。</p><h3 id="_3-context-——-看它现在脑子里装着什么" tabindex="-1">3. <code>/context</code> —— 看它现在脑子里装着什么 <a class="header-anchor" href="#_3-context-——-看它现在脑子里装着什么" aria-label="Permalink to &quot;3. `/context` —— 看它现在脑子里装着什么&quot;">​</a></h3><p>对话变长以后，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/context</span></span></code></pre></div><p>它会显示上下文窗口被什么占满了（文件、工具输出、记忆），并告诉你哪些地方在浪费空间。满了就会变慢、变笨，这时候用 <code>/compact</code> 压缩，或 <code>/clear</code> 重开。</p><h2 id="退出对话" tabindex="-1">退出对话 <a class="header-anchor" href="#退出对话" aria-label="Permalink to &quot;退出对话&quot;">​</a></h2><p>三种方式：</p><ol><li>输入 <code>/exit</code> 并回车</li><li>连按两次 <code>Ctrl + C</code></li><li><code>Ctrl + D</code></li></ol><div class="tip custom-block"><p class="custom-block-title">关掉 ≠ 丢掉</p><p>会话会自动保存。下次想接着聊，运行 <code>claude --continue</code> 接着上一次，或 <code>claude --resume</code> 从列表里挑一个。详见第七章。</p></div><h2 id="怎么问问题效果最好" tabindex="-1">怎么问问题效果最好？ <a class="header-anchor" href="#怎么问问题效果最好" aria-label="Permalink to &quot;怎么问问题效果最好？&quot;">​</a></h2><h3 id="模糊-vs-具体" tabindex="-1">模糊 vs 具体 <a class="header-anchor" href="#模糊-vs-具体" aria-label="Permalink to &quot;模糊 vs 具体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>效果不好的问法</th><th>效果好的问法</th></tr></thead><tbody><tr><td>&quot;代码有问题&quot;</td><td>&quot;这个函数报 TypeError: Cannot read property &#39;x&#39; of undefined&quot;</td></tr><tr><td>&quot;帮我看看&quot;</td><td>&quot;帮我看看 <code>src/calc.js</code> 里的 <code>calculateSum</code> 函数&quot;</td></tr><tr><td>&quot;能帮我吗&quot;</td><td>&quot;写一个计算两数之和的函数，放在 <code>src/calc.js</code>，加个测试&quot;</td></tr></tbody></table><p>越具体，它要猜的东西越少，回答越准。</p><h3 id="它看不见的东西-得你告诉它" tabindex="-1">它看不见的东西，得你告诉它 <a class="header-anchor" href="#它看不见的东西-得你告诉它" aria-label="Permalink to &quot;它看不见的东西，得你告诉它&quot;">​</a></h3><p>它读不到你脑子里的东西：为什么要做这个改动、哪个文件绝对不能动、部署流程是什么。这类信息要么写进 <code>CLAUDE.md</code>，要么在提问时直接说。</p><h3 id="给它一个能自己检查的办法" tabindex="-1">给它一个能自己检查的办法 <a class="header-anchor" href="#给它一个能自己检查的办法" aria-label="Permalink to &quot;给它一个能自己检查的办法&quot;">​</a></h3><p>比&quot;改对了吗？&quot;更有效的是&quot;跑一下 <code>npm test</code> 看是否通过&quot;。有可验证的标准，它就能自己迭代到正确。</p><h2 id="常用提问示例" tabindex="-1">常用提问示例 <a class="header-anchor" href="#常用提问示例" aria-label="Permalink to &quot;常用提问示例&quot;">​</a></h2><h3 id="理解代码库" tabindex="-1">理解代码库 <a class="header-anchor" href="#理解代码库" aria-label="Permalink to &quot;理解代码库&quot;">​</a></h3><p>它会按需自己读文件，你不必手动粘贴代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个项目是做什么的？</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个项目用什么技术栈？主入口在哪里？</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释一下目录结构，哪些是核心代码</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户的登录流程是怎么走的？从哪个路由进来？</span></span></code></pre></div><h3 id="动手改" tabindex="-1">动手改 <a class="header-anchor" href="#动手改" aria-label="Permalink to &quot;动手改&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我给 hello.py 加个命令行参数，默认输出当前时间</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这段代码哪里有 bug？先解释原因，再给修复方案，我来决定用哪个</span></span></code></pre></div><h3 id="其他常见问题" tabindex="-1">其他常见问题 <a class="header-anchor" href="#其他常见问题" aria-label="Permalink to &quot;其他常见问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我解释一下 src/utils.js 这个文件</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个目录下的文件名按 日期_标题.md 的格式批量重命名，先列个清单给我看</span></span></code></pre></div><h2 id="claude-的回答格式" tabindex="-1">Claude 的回答格式 <a class="header-anchor" href="#claude-的回答格式" aria-label="Permalink to &quot;Claude 的回答格式&quot;">​</a></h2><p>它的回复通常包含：</p><ol><li><strong>解释</strong>：它在做什么、为什么</li><li><strong>改动</strong>：编辑文件时会显示 diff（新增绿、删除红）</li><li><strong>建议</strong>：还能怎么改进</li></ol><p>改文件时它会<strong>请求许可</strong>（自动模式下，安全改动直接执行）。看到 diff 别急着按回车，扫一眼再放行。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 回答很慢？</strong></p><p>A: 正在生成，稍等。长任务可以按 <code>Esc</code> 中断，然后让它&quot;先给计划，别动代码&quot;。</p><p><strong>Q: 回答被截断了？</strong></p><p>A: 输入「继续」，让它说完。</p><p><strong>Q: 答非所问？</strong></p><p>A: 换个更具体的问法，或者直接 <code>@</code> 指定文件，比如 <code>@src/auth.js 这里的超时是怎么设的？</code></p><p><strong>Q: 它说改了，但我没看到变化？</strong></p><p>A: 运行 <code>/diff</code> 看它到底改了什么。如果什么都没改，说明它只是描述方案没动手，直接说「按这个方案改」。</p><p><strong>Q: 改坏了怎么办？</strong></p><p>A: <code>/rewind</code> 可以回滚代码和对话到任意一个检查点。这是最常用的后悔药。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>在任意项目里运行 <code>claude</code>，问「这个项目是做什么的？」</li><li>运行 <code>/init</code>，打开生成的 <code>CLAUDE.md</code> 看看它写了什么，删掉不对的部分</li><li>按 <code>Shift + Tab</code>，观察输入框下方的模式提示怎么变</li><li>运行 <code>/context</code>，看当前的上下文占用</li></ol><h2 id="入门篇总结" tabindex="-1">入门篇总结 <a class="header-anchor" href="#入门篇总结" aria-label="Permalink to &quot;入门篇总结&quot;">​</a></h2><p>到这里你已经能跑起来了。回顾一下手上的工具：</p><ul><li><strong>装好了</strong> <code>claude</code>（第二章）</li><li><strong>配好了</strong>账号（第三章，官方订阅或中转）</li><li><strong>会开话术</strong>：<code>cd</code> → <code>claude</code> → 提问</li><li><strong>三个入口</strong>：<code>Shift+Tab</code>（权限）、<code>/init</code>（认识项目）、<code>/context</code>（看上下文）</li><li><strong>一个后悔药</strong>：<code>/rewind</code></li></ul><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>接下来进入基础篇，学怎么让它真正读懂你的代码库。</p><p><a href="/claude-code-guide/guide/2-basic-usage/5-understand-codebase.html">👉 第五章：读懂代码库</a></p>',71)])])}const b=e(i,[["render",d]]);export{u as __pageData,b as default};
